"""Versioned audit-event model: ``rig.audit-event/v2`` in ``rig.audit-envelope/v1`` (M2-B).

An event records one policy decision, grouped by where each value came from:

* ``audit``  - generated by the audit layer (ids, time, redaction mode);
* ``engine`` - copied from the M1 :class:`DecisionRecord` (the decision);
* ``caller`` - **claims made by the caller** of the engine. They are only
  present when the request re-parses to the record's ``request_digest``
  (``consistent``). Consistency is not authentication: the engine never
  verified who the caller is.

Events never contain raw requests, tool arguments, prompts, credentials,
exception messages, persistence status, or any claim that a tool ran or that
a decision was enforced (``engine.enforced`` is always ``false``).

The envelope carries the event, its SHA-256 ``event_digest`` and an optional
HMAC authenticator. All models are frozen and validate themselves on
construction.
"""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from enum import StrEnum
from typing import Any

from rig_sentinel.audit import validation as v
from rig_sentinel.audit.chain import (
    MAC_ALGORITHM,
    AuthStatus,
    compute_mac,
    event_digest,
    macs_equal,
)
from rig_sentinel.audit.errors import AuditError, AuditErrorCode
from rig_sentinel.audit.keys import AuditKey, KeyPurpose
from rig_sentinel.policy.canonical import canonical_json
from rig_sentinel.policy.model import MAX_REQUEST_LABELS, Assurance, Decision, Environment, OperationClass
from rig_sentinel.policy.reasons import ReasonCode
from rig_sentinel.policy.resources import ResourceKind

AUDIT_EVENT_SCHEMA = "rig.audit-event/v2"
AUDIT_EVENT_SCHEMA_V3 = "rig.audit-event/v3"
SUPPORTED_EVENT_SCHEMAS = (AUDIT_EVENT_SCHEMA, AUDIT_EVENT_SCHEMA_V3)
AUDIT_ENVELOPE_SCHEMA = "rig.audit-envelope/v1"

# Readable-label vocabulary for v3 (B2-P1): exactly the policy labels documented in
# docs/POLICY_ENGINE.md. Every other label is pseudonymized or omitted. Extending this set
# is a schema and privacy decision that needs review; there is no free-text exception.
APPROVED_READABLE_LABELS = frozenset({"reviewed", "untrusted_content_present"})


class RedactionMode(StrEnum):
    SCOPED = "scoped"  # keyed pseudonyms (K_ref present)
    NO_REF_KEY = "no-ref-key"  # no K_ref: no pseudonyms, no authority, no digests


class IdentityMode(StrEnum):
    """How v3 events represent caller identities (agent, tool, labels)."""

    PSEUDONYMIZED = "pseudonymized"  # keyed HMAC references under K_ref
    OMITTED = "omitted"  # no K_ref: no identity material at all


class RequestConsistency(StrEnum):
    CONSISTENT = "consistent"  # re-parsed request matches the record's request_digest
    INVALID_REQUEST = "invalid_request"  # the request does not parse
    MISMATCH = "mismatch"  # it parses, but to a different digest (changed or hostile)
    NOT_APPLICABLE = "not_applicable"  # the record has no request_digest to compare


EVENT_FIELDS = frozenset({"schema_version", "audit", "engine", "caller"})
AUDIT_FIELDS = frozenset({"event_id", "correlation_id", "recorded_at", "redaction_mode", "ref_key_id"})
ENGINE_FIELDS = frozenset(
    {
        "decision", "reason_code", "decision_ref", "protected", "enforced", "record_schema",
        "engine_version", "evaluated_at", "policy_id", "policy_version", "policy_sha256",
        "deciding_rule_ids", "deciding_rule_count", "matched_rule_ids", "matched_rule_count",
        "approval", "error_class", "request_digest",
    }
)
APPROVAL_FIELDS = frozenset(
    {"eligible_approvers", "eligible_approver_count", "request_binding_sha256", "ttl_seconds"}
)
CALLER_FIELDS = frozenset(
    {
        "consistency", "agent_id", "assurance_claim", "tool_id", "manifest_sha256", "operation",
        "environment", "labels", "resource", "session_ref", "request_ref", "redacted_fields",
    }
)
CALLER_V3_FIELDS = frozenset(
    {
        "consistency", "identity_mode", "agent_ref", "assurance_claim", "tool_ref",
        "manifest_ref", "operation", "environment", "readable_labels", "label_refs",
        "omitted_labels_count", "resource", "session_ref", "request_ref",
    }
)
RESOURCE_FIELDS = frozenset({"kind", "depth", "authority_ref", "resource_ref"})
ENVELOPE_FIELDS = frozenset({"envelope_schema", "event", "event_digest", "auth"})
AUTH_FIELDS = frozenset({"algorithm", "key_id", "mac"})


def _value(item: Any) -> Any:
    return None if item is None else item.value


@dataclass(frozen=True)
class AuditSection:
    event_id: str
    correlation_id: str
    recorded_at: str
    redaction_mode: RedactionMode
    ref_key_id: str | None

    def __post_init__(self) -> None:
        v.require_hex32(self.event_id, "audit.event_id")
        v.require_hex32(self.correlation_id, "audit.correlation_id")
        v.require_timestamp(self.recorded_at, "audit.recorded_at")
        v.require_enum(self.redaction_mode, RedactionMode, "audit.redaction_mode")
        v.optional(v.require_hex32, self.ref_key_id, "audit.ref_key_id")

    def to_dict(self) -> dict[str, Any]:
        return {
            "event_id": self.event_id,
            "correlation_id": self.correlation_id,
            "recorded_at": self.recorded_at,
            "redaction_mode": self.redaction_mode.value,
            "ref_key_id": self.ref_key_id,
        }


@dataclass(frozen=True)
class ApprovalSection:
    eligible_approvers: tuple[str, ...]
    eligible_approver_count: int
    request_binding_sha256: str
    ttl_seconds: int

    def __post_init__(self) -> None:
        path = "engine.approval"
        v.require_identifier_tuple(self.eligible_approvers, f"{path}.eligible_approvers")
        v.require_int(self.eligible_approver_count, f"{path}.eligible_approver_count", 0, v.MAX_COUNT)
        if self.eligible_approver_count < len(self.eligible_approvers):
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, f"{path}.eligible_approver_count")
        v.require_sha256(self.request_binding_sha256, f"{path}.request_binding_sha256")
        v.require_int(self.ttl_seconds, f"{path}.ttl_seconds", v.MIN_APPROVAL_TTL, v.MAX_APPROVAL_TTL)

    def to_dict(self) -> dict[str, Any]:
        return {
            "eligible_approvers": list(self.eligible_approvers),
            "eligible_approver_count": self.eligible_approver_count,
            "request_binding_sha256": self.request_binding_sha256,
            "ttl_seconds": self.ttl_seconds,
        }


@dataclass(frozen=True)
class EngineSection:
    decision: Decision
    reason_code: ReasonCode
    decision_ref: str
    protected: bool
    enforced: bool
    record_schema: str
    engine_version: str
    evaluated_at: str | None
    policy_id: str | None
    policy_version: str | None
    policy_sha256: str | None
    deciding_rule_ids: tuple[str, ...]
    deciding_rule_count: int
    matched_rule_ids: tuple[str, ...]
    matched_rule_count: int
    approval: ApprovalSection | None
    error_class: str | None
    request_digest: str | None

    def __post_init__(self) -> None:
        v.require_enum(self.decision, Decision, "engine.decision")
        v.require_enum(self.reason_code, ReasonCode, "engine.reason_code")
        v.require_sha256(self.decision_ref, "engine.decision_ref")
        v.require_bool(self.protected, "engine.protected")
        if v.require_bool(self.enforced, "engine.enforced") is not False:
            raise AuditError(AuditErrorCode.INVALID_FIELD, "engine.enforced")
        v.require_schema_tag(self.record_schema, "engine.record_schema")
        v.require_engine_version(self.engine_version, "engine.engine_version")
        v.optional(v.require_timestamp, self.evaluated_at, "engine.evaluated_at")
        v.optional(v.require_identifier, self.policy_id, "engine.policy_id")
        v.optional(v.require_policy_version, self.policy_version, "engine.policy_version")
        v.optional(v.require_sha256, self.policy_sha256, "engine.policy_sha256")
        for ids, count, name in (
            (self.deciding_rule_ids, self.deciding_rule_count, "deciding_rule"),
            (self.matched_rule_ids, self.matched_rule_count, "matched_rule"),
        ):
            v.require_identifier_tuple(ids, f"engine.{name}_ids")
            v.require_int(count, f"engine.{name}_count", 0, v.MAX_COUNT)
            if count < len(ids):
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, f"engine.{name}_count")
        if self.approval is not None:
            if type(self.approval) is not ApprovalSection:
                raise AuditError(AuditErrorCode.INVALID_FIELD, "engine.approval")
            if self.decision is not Decision.REQUIRE_APPROVAL:
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "engine.approval")
        v.optional(v.require_error_class, self.error_class, "engine.error_class")
        v.optional(v.require_sha256, self.request_digest, "engine.request_digest")

    def to_dict(self) -> dict[str, Any]:
        return {
            "decision": self.decision.value,
            "reason_code": self.reason_code.value,
            "decision_ref": self.decision_ref,
            "protected": self.protected,
            "enforced": self.enforced,
            "record_schema": self.record_schema,
            "engine_version": self.engine_version,
            "evaluated_at": self.evaluated_at,
            "policy_id": self.policy_id,
            "policy_version": self.policy_version,
            "policy_sha256": self.policy_sha256,
            "deciding_rule_ids": list(self.deciding_rule_ids),
            "deciding_rule_count": self.deciding_rule_count,
            "matched_rule_ids": list(self.matched_rule_ids),
            "matched_rule_count": self.matched_rule_count,
            "approval": None if self.approval is None else self.approval.to_dict(),
            "error_class": self.error_class,
            "request_digest": self.request_digest,
        }


@dataclass(frozen=True)
class ResourceSection:
    """A minimized resource: its kind and depth, plus keyed references when K_ref exists."""

    kind: ResourceKind
    depth: int
    authority_ref: str | None
    resource_ref: str | None

    def __post_init__(self) -> None:
        v.require_enum(self.kind, ResourceKind, "caller.resource.kind")
        v.require_int(self.depth, "caller.resource.depth", 0, v.MAX_DEPTH)
        v.optional(v.require_hex32, self.authority_ref, "caller.resource.authority_ref")
        v.optional(v.require_hex32, self.resource_ref, "caller.resource.resource_ref")

    def to_dict(self) -> dict[str, Any]:
        return {
            "kind": self.kind.value,
            "depth": self.depth,
            "authority_ref": self.authority_ref,
            "resource_ref": self.resource_ref,
        }


@dataclass(frozen=True)
class CallerSection:
    """What the caller *claimed*. Never authenticated by the engine or the audit layer."""

    consistency: RequestConsistency
    agent_id: str | None
    assurance_claim: Assurance | None
    tool_id: str | None
    manifest_sha256: str | None
    operation: OperationClass | None
    environment: Environment | None
    labels: tuple[str, ...] | None
    resource: ResourceSection | None
    session_ref: str | None
    request_ref: str | None
    redacted_fields: int

    def __post_init__(self) -> None:
        v.require_enum(self.consistency, RequestConsistency, "caller.consistency")
        v.optional(v.require_identifier, self.agent_id, "caller.agent_id")
        if self.assurance_claim is not None:
            v.require_enum(self.assurance_claim, Assurance, "caller.assurance_claim")
        v.optional(v.require_tool_id, self.tool_id, "caller.tool_id")
        v.optional(v.require_sha256, self.manifest_sha256, "caller.manifest_sha256")
        if self.operation is not None:
            v.require_enum(self.operation, OperationClass, "caller.operation")
        if self.environment is not None:
            v.require_enum(self.environment, Environment, "caller.environment")
        v.optional(v.require_identifier_tuple, self.labels, "caller.labels")
        if self.resource is not None and type(self.resource) is not ResourceSection:
            raise AuditError(AuditErrorCode.INVALID_FIELD, "caller.resource")
        v.optional(v.require_hex32, self.session_ref, "caller.session_ref")
        v.optional(v.require_hex32, self.request_ref, "caller.request_ref")
        v.require_int(self.redacted_fields, "caller.redacted_fields", 0, v.MAX_REDACTED_FIELDS)

        claims = (
            self.agent_id, self.assurance_claim, self.tool_id, self.manifest_sha256,
            self.operation, self.environment, self.labels, self.resource,
            self.session_ref, self.request_ref,
        )
        if self.consistency is RequestConsistency.CONSISTENT:
            required = (self.assurance_claim, self.operation, self.environment, self.labels, self.resource)
            if any(item is None for item in required):
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller")
        elif any(item is not None for item in claims) or self.redacted_fields:
            # Claims are recorded only when the request is consistent with the decision.
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller")

    def to_dict(self) -> dict[str, Any]:
        return {
            "consistency": self.consistency.value,
            "agent_id": self.agent_id,
            "assurance_claim": _value(self.assurance_claim),
            "tool_id": self.tool_id,
            "manifest_sha256": self.manifest_sha256,
            "operation": _value(self.operation),
            "environment": _value(self.environment),
            "labels": None if self.labels is None else list(self.labels),
            "resource": None if self.resource is None else self.resource.to_dict(),
            "session_ref": self.session_ref,
            "request_ref": self.request_ref,
            "redacted_fields": self.redacted_fields,
        }


@dataclass(frozen=True)
class AuditEvent:
    audit: AuditSection
    engine: EngineSection
    caller: CallerSection

    def __post_init__(self) -> None:
        for section, kind, path in (
            (self.audit, AuditSection, "audit"),
            (self.engine, EngineSection, "engine"),
            (self.caller, CallerSection, "caller"),
        ):
            if type(section) is not kind:
                raise AuditError(AuditErrorCode.INVALID_FIELD, path)

        keyed = (
            self.caller.session_ref,
            self.caller.request_ref,
            None if self.caller.resource is None else self.caller.resource.authority_ref,
            None if self.caller.resource is None else self.caller.resource.resource_ref,
        )
        if self.audit.redaction_mode is RedactionMode.NO_REF_KEY:
            if self.audit.ref_key_id is not None or any(item is not None for item in keyed):
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "audit.redaction_mode")
        elif self.audit.ref_key_id is None:
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "audit.ref_key_id")

        consistent = self.caller.consistency is RequestConsistency.CONSISTENT
        if consistent and self.engine.request_digest is None:
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.consistency")
        if self.caller.consistency is RequestConsistency.NOT_APPLICABLE and (
            self.engine.request_digest is not None
        ):
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.consistency")

        if len(self.canonical_bytes()) > v.MAX_EVENT_BYTES:
            raise AuditError(AuditErrorCode.LIMIT_EXCEEDED, "")

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": AUDIT_EVENT_SCHEMA,
            "audit": self.audit.to_dict(),
            "engine": self.engine.to_dict(),
            "caller": self.caller.to_dict(),
        }

    def canonical_bytes(self) -> bytes:
        return canonical_json(self.to_dict())

    @property
    def digest(self) -> str:
        return event_digest(self.to_dict())


@dataclass(frozen=True)
class CallerSectionV3:
    """v3 caller claims (B2-P1): identities are keyed references or omitted, never plaintext.

    Readable: closed enumerations (assurance claim, operation, environment), the minimized
    resource, and labels from APPROVED_READABLE_LABELS. The tool manifest digest identifies
    the tool, so it is recorded only as ``manifest_ref`` (a K_ref reference in its own
    namespace) and never in clear.

    ``omitted_labels_count`` (omitted mode only) is the exact number of labels that were left
    out because no K_ref was available to reference them: an int from 0 to
    ``MAX_REQUEST_LABELS - len(readable_labels)``, 0 when nothing was omitted. It is ``None``
    in pseudonymized mode (every such label becomes a ``label_refs`` entry) and whenever the
    request is not ``consistent``.
    """

    consistency: RequestConsistency
    identity_mode: IdentityMode
    agent_ref: str | None
    assurance_claim: Assurance | None
    tool_ref: str | None
    manifest_ref: str | None
    operation: OperationClass | None
    environment: Environment | None
    readable_labels: tuple[str, ...] | None
    label_refs: tuple[str, ...] | None
    omitted_labels_count: int | None
    resource: ResourceSection | None
    session_ref: str | None
    request_ref: str | None

    def __post_init__(self) -> None:
        v.require_enum(self.consistency, RequestConsistency, "caller.consistency")
        v.require_enum(self.identity_mode, IdentityMode, "caller.identity_mode")
        v.optional(v.require_hex32, self.agent_ref, "caller.agent_ref")
        if self.assurance_claim is not None:
            v.require_enum(self.assurance_claim, Assurance, "caller.assurance_claim")
        v.optional(v.require_hex32, self.tool_ref, "caller.tool_ref")
        v.optional(v.require_hex32, self.manifest_ref, "caller.manifest_ref")
        if self.operation is not None:
            v.require_enum(self.operation, OperationClass, "caller.operation")
        if self.environment is not None:
            v.require_enum(self.environment, Environment, "caller.environment")
        if self.readable_labels is not None:
            v.require_identifier_tuple(self.readable_labels, "caller.readable_labels")
            if not set(self.readable_labels) <= APPROVED_READABLE_LABELS:
                raise AuditError(AuditErrorCode.INVALID_FIELD, "caller.readable_labels")
        v.optional(v.require_hex32_tuple, self.label_refs, "caller.label_refs")
        v.optional(v.require_int, self.omitted_labels_count, "caller.omitted_labels_count", 0, MAX_REQUEST_LABELS)
        if self.resource is not None and type(self.resource) is not ResourceSection:
            raise AuditError(AuditErrorCode.INVALID_FIELD, "caller.resource")
        v.optional(v.require_hex32, self.session_ref, "caller.session_ref")
        v.optional(v.require_hex32, self.request_ref, "caller.request_ref")

        identity = (self.agent_ref, self.tool_ref, self.label_refs)
        claims = identity + (
            self.assurance_claim, self.manifest_ref, self.operation, self.environment,
            self.readable_labels, self.omitted_labels_count, self.resource, self.session_ref,
            self.request_ref,
        )
        if self.consistency is not RequestConsistency.CONSISTENT:
            if any(item is not None for item in claims):
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller")
            return
        required = (self.assurance_claim, self.operation, self.environment, self.readable_labels, self.resource)
        if any(item is None for item in required):
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller")
        readable_count = len(self.readable_labels)
        if self.identity_mode is IdentityMode.PSEUDONYMIZED:
            if any(item is None for item in identity):
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.identity_mode")
            if self.omitted_labels_count is not None:  # nothing is omitted when K_ref exists
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.omitted_labels_count")
            label_total, label_path = readable_count + len(self.label_refs), "caller.label_refs"
        else:
            keyed = identity + (self.manifest_ref, self.session_ref, self.request_ref)
            if any(item is not None for item in keyed):
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.identity_mode")
            if self.omitted_labels_count is None:  # zero, never absent, in omitted mode
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.omitted_labels_count")
            label_total, label_path = readable_count + self.omitted_labels_count, "caller.omitted_labels_count"
        if label_total > MAX_REQUEST_LABELS:  # M1 accepts at most MAX_REQUEST_LABELS unique labels
            raise AuditError(AuditErrorCode.LIMIT_EXCEEDED, label_path)

    def to_dict(self) -> dict[str, Any]:
        return {
            "consistency": self.consistency.value,
            "identity_mode": self.identity_mode.value,
            "agent_ref": self.agent_ref,
            "assurance_claim": _value(self.assurance_claim),
            "tool_ref": self.tool_ref,
            "manifest_ref": self.manifest_ref,
            "operation": _value(self.operation),
            "environment": _value(self.environment),
            "readable_labels": None if self.readable_labels is None else list(self.readable_labels),
            "label_refs": None if self.label_refs is None else list(self.label_refs),
            "omitted_labels_count": self.omitted_labels_count,
            "resource": None if self.resource is None else self.resource.to_dict(),
            "session_ref": self.session_ref,
            "request_ref": self.request_ref,
        }


@dataclass(frozen=True)
class AuditEventV3:
    """``rig.audit-event/v3``: same audit and engine sections as v2, privacy-hardened caller."""

    audit: AuditSection
    engine: EngineSection
    caller: CallerSectionV3

    def __post_init__(self) -> None:
        for section, kind, path in (
            (self.audit, AuditSection, "audit"),
            (self.engine, EngineSection, "engine"),
            (self.caller, CallerSectionV3, "caller"),
        ):
            if type(section) is not kind:
                raise AuditError(AuditErrorCode.INVALID_FIELD, path)

        scoped = self.audit.redaction_mode is RedactionMode.SCOPED
        if scoped != (self.audit.ref_key_id is not None):
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "audit.ref_key_id")
        expected_mode = IdentityMode.PSEUDONYMIZED if scoped else IdentityMode.OMITTED
        if self.caller.identity_mode is not expected_mode:
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.identity_mode")
        if not scoped:
            resource = self.caller.resource
            keyed = (
                self.caller.agent_ref, self.caller.tool_ref, self.caller.label_refs,
                self.caller.manifest_ref, self.caller.session_ref, self.caller.request_ref,
                None if resource is None else resource.authority_ref,
                None if resource is None else resource.resource_ref,
            )
            if any(item is not None for item in keyed):
                raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "audit.redaction_mode")

        consistency = self.caller.consistency
        if consistency is RequestConsistency.CONSISTENT and self.engine.request_digest is None:
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.consistency")
        if consistency is RequestConsistency.NOT_APPLICABLE and self.engine.request_digest is not None:
            raise AuditError(AuditErrorCode.INCONSISTENT_EVENT, "caller.consistency")

        if len(self.canonical_bytes()) > v.MAX_EVENT_BYTES:
            raise AuditError(AuditErrorCode.LIMIT_EXCEEDED, "")

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": AUDIT_EVENT_SCHEMA_V3,
            "audit": self.audit.to_dict(),
            "engine": self.engine.to_dict(),
            "caller": self.caller.to_dict(),
        }

    def canonical_bytes(self) -> bytes:
        return canonical_json(self.to_dict())

    @property
    def digest(self) -> str:
        return event_digest(self.to_dict())


def _is_event(value: object) -> bool:
    """Identity-only check: no ``==`` on attacker-controlled types (metaclass __eq__)."""
    kind = type(value)
    return kind is AuditEvent or kind is AuditEventV3


@dataclass(frozen=True)
class AuthTag:
    algorithm: str
    key_id: str
    mac: str

    def __post_init__(self) -> None:
        if type(self.algorithm) is not str or self.algorithm != MAC_ALGORITHM:
            raise AuditError(AuditErrorCode.INVALID_FIELD, "auth.algorithm")
        v.require_hex32(self.key_id, "auth.key_id")
        v.require_sha256(self.mac, "auth.mac")

    def to_dict(self) -> dict[str, Any]:
        return {"algorithm": self.algorithm, "key_id": self.key_id, "mac": self.mac}


@dataclass(frozen=True)
class AuditEnvelope:
    """An event with its digest and an optional HMAC tag. Stored state is never inside it."""

    event: AuditEvent | AuditEventV3
    event_digest: str
    auth: AuthTag | None

    def __post_init__(self) -> None:
        if not _is_event(self.event):
            raise AuditError(AuditErrorCode.INVALID_FIELD, "event")
        v.require_sha256(self.event_digest, "event_digest")
        if self.auth is not None and type(self.auth) is not AuthTag:
            raise AuditError(AuditErrorCode.INVALID_FIELD, "auth")
        if len(self.canonical_bytes()) > v.MAX_ENVELOPE_BYTES:
            raise AuditError(AuditErrorCode.LIMIT_EXCEEDED, "")

    @classmethod
    def seal(cls, event: AuditEvent | AuditEventV3, auth_key: AuditKey | None) -> AuditEnvelope:
        """Wrap ``event``; authenticate it when ``auth_key`` is given.

        v2 and v3 events use the same, unchanged digest and MAC construction; the event's
        ``schema_version`` is part of the authenticated content.
        """
        if not _is_event(event):
            raise AuditError(AuditErrorCode.INVALID_FIELD, "event")
        body = event.to_dict()
        auth = None
        if auth_key is not None:
            if type(auth_key) is not AuditKey or auth_key.purpose is not KeyPurpose.AUTH:
                raise AuditError(AuditErrorCode.KEY_PURPOSE_MISMATCH, "auth")
            auth = AuthTag(MAC_ALGORITHM, auth_key.key_id, compute_mac(auth_key, body))
        return cls(event=event, event_digest=event_digest(body), auth=auth)

    def verify(self, keys: Mapping[str, AuditKey]) -> AuthStatus:
        """Check the digest and, if present, the MAC. Never raises for bad content."""
        body = self.event.to_dict()
        if not macs_equal(event_digest(body), self.event_digest):
            return AuthStatus.DIGEST_MISMATCH
        if self.auth is None:
            return AuthStatus.UNAUTHENTICATED
        key = keys.get(self.auth.key_id) if isinstance(keys, Mapping) else None
        if type(key) is not AuditKey or key.purpose is not KeyPurpose.AUTH:
            return AuthStatus.UNKNOWN_KEY
        if macs_equal(compute_mac(key, body), self.auth.mac):
            return AuthStatus.AUTHENTIC
        return AuthStatus.MAC_MISMATCH

    def to_dict(self) -> dict[str, Any]:
        return {
            "envelope_schema": AUDIT_ENVELOPE_SCHEMA,
            "event": self.event.to_dict(),
            "event_digest": self.event_digest,
            "auth": None if self.auth is None else self.auth.to_dict(),
        }

    def canonical_bytes(self) -> bytes:
        return canonical_json(self.to_dict())


def verify_envelope_dict(data: object, keys: Mapping[str, AuditKey]) -> AuthStatus:
    """Verify an envelope given as untrusted data (for example ``json.loads`` output)."""
    try:
        envelope = v.envelope_from_dict(data)
    except AuditError:
        return AuthStatus.SCHEMA_INVALID
    return envelope.verify(keys)
